namespace Ordering;

/// <summary>Handles product returns by coordinating validation, refunds and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnRegistry _returnRegistry = new();
    private readonly RefundService _refundService = new();
    private readonly RestockService _restockService = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        var validationResult = ReturnValidator.ValidateForProcessing(
            order,
            customer,
            _returnRegistry.IsProcessed);

        if (validationResult is not null)
            return validationResult;

        _restockService.QueueReturn(order);
        if (!_restockService.HasQueuedStock)
            return "no returnable lines";

        _returnRegistry.MarkProcessed(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order) =>
        ReturnValidator.IsReturnable(order, _returnRegistry.IsProcessed);

    public decimal ComputeRefund(Order order) => _refundService.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundService.Log(order, amount);

    public int Restock(Order order) => _restockService.Restock(order);
}

internal sealed class ReturnRegistry
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

    public bool IsProcessed(string reference) =>
        _processedReferences.Contains(reference);

    public void MarkProcessed(string reference) =>
        _processedReferences.Add(reference);
}

internal static class ReturnValidator
{
    public static string? ValidateForProcessing(
        Order order,
        Customer customer,
        Func<string, bool> isProcessed)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (isProcessed(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity > 100)
                return "quantity too high";
        }

        return null;
    }

    public static bool IsReturnable(Order order, Func<string, bool> isProcessed)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (isProcessed(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity >= 1 &&
                line.Quantity <= 100 &&
                !string.IsNullOrEmpty(line.Sku))
            {
                return true;
            }
        }

        return false;
    }
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            refund += CalculateLineRefund(line.Quantity);
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _refundLog.Add(FormatEntry(order.Reference, amount));
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    private static decimal CalculateLineRefund(int quantity)
    {
        if (quantity <= 0)
            return 0m;
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;

        return quantity > 1 ? quantity * UnitRefund : UnitRefund;
    }

    private string FormatEntry(string reference, decimal amount)
    {
        if (_refundLog.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}

internal sealed class RestockService
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public bool HasQueuedStock => _restockBySku.Count != 0;

    public void QueueReturn(Order order)
    {
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var count)
                ? count + line.Quantity
                : line.Quantity;
        }
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (!IsValidRestockLine(line.Quantity, line.Sku))
                continue;

            var sku = line.Sku;
            if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[sku] = 0;
            }
            else
            {
                _restockBySku[sku] = line.Quantity > 50
                    ? line.Quantity / 2
                    : line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }

    private static bool IsValidRestockLine(int quantity, string sku) =>
        quantity > 0 && quantity <= 100 && !string.IsNullOrEmpty(sku);
}
